INSERT
  INTO TB_RESOURCE (
              RESOURCE_SEQ
            , REF_TP
            , FILE_TP
            , FILE_NM
            , FILE_PATH
            , FILE_EXTN
            , FILE_SZ
            , FILE_CONTS_TP
            , REG_USER_SEQ
            , REG_IP
            )
       VALUES (
              nextval('tb_resource_file_seq_seq')
            , #{refTp}
            , #{fileTp}
            , #{fileNm}
            , #{filePath}
            , #{fileExtn}
            , #{fileSz}
            , #{fileContsTp}
            , #{loginUserSeq}
            , #{loginUserIp}
            )

